import{_ as a,o as r,c as s,j as e,a as o}from"./chunks/framework.QCr1ZR1X.js";const p=JSON.parse('{"title":"思维导图-第2章-工业互联网基础","description":"","frontmatter":{},"headers":[],"relativePath":"mindmap/思维导图-第2章-工业互联网基础.md","filePath":"mindmap/思维导图-第2章-工业互联网基础.md","lastUpdated":1786967935000}'),n={name:"mindmap/思维导图-第2章-工业互联网基础.md"};function d(i,t,c,l,m,_){return r(),s("div",null,[...t[0]||(t[0]=[e("h1",{id:"思维导图-第2章-工业互联网基础",tabindex:"-1"},[o("思维导图-第2章-工业互联网基础 "),e("a",{class:"header-anchor",href:"#思维导图-第2章-工业互联网基础","aria-label":'Permalink to "思维导图-第2章-工业互联网基础"'},"​")],-1),e("div",{class:"mermaid"},'# 第2章 工业互联网基础 — 思维导图 ## 2.1 从"黑灯工厂"看工业互联网的本质 ### 走进真实的智能工厂 - 小米亦庄智能工厂 - 95%自动化率 - 关键工序100%自动化 - 特斯拉上海超级工厂 - 300+台机器人 - 焊装车间火星四溅 - 三一重工18号厂房 - 产能提升123% - 人员效率提升98% - 制造成本降低29% ### 什么是"闭环"？ - 类比：空调自动模式 - 五步闭环：感知 → 传输 → 分析 → 决策 → 执行 → 再感知 ### 工业互联网的起源与定义 - 四条技术线索 - 制造业自动化（PLC/DCS/CNC） - 企业信息化（ERP） - 物联网（IoT） - 大数据与人工智能 - 三股力量 - 德国工业4.0（2011，柔性生产） - 美国工业互联网（2012，GE白皮书，预测性维护） - 中国制造2025（2015/2017，两化融合） - GE白皮书四个要点 - 智能机器、高级分析、人与机器协同、物理与数字融合 - 四项关键技术 - 传感技术（低成本高精度） - 通信技术（5G/TSN） - 云计算（弹性伸缩） - AI与机器学习（自动学习规律） - 工业互联网定义 - IIC定义：人-机-物互联 - AII定义：新型基础设施/应用模式/工业生态 - 学术界共识：全面互联+智能决策+网络化协同+精准化控制 - 消费互联网 vs 工业互联网（七个维度） - 连接对象、数据方向、可靠性、延迟、工作环境、安全后果、数据特征 ## 2.2 动手实践：SSH远程管理与Linux命令入门 ### 实践任务 - 安装并启动SSH服务 - sudo apt install openssh-server - systemctl管理 - 从Windows SSH远程登录Ubuntu - ssh student@IP - Linux常用命令九个 - pwd、ls、cd、mkdir、touch、nano、cat、tree、rm - apt软件包管理 - sudo apt update/install/remove - 类比手机应用商店 - 安装curl并实际使用 - curl ifconfig.me（查公网IP） - curl wttr.in（查天气） ## 2.3 工业互联网参考架构与系统构成 ### IIRA四层参考架构 - 业务层：ERP/SCM/PLM - 应用层：MES/数字孪生/预测性维护 - 平台层：数据存储/分析引擎/AI模型 - 边缘层：传感器/PLC/网关/执行器 ### 两个数据流动场景 - 预测性维护 - 传感器 → 智能网关 → 云平台AI分析 → 预警推送维修APP → OEE报表 - 完整数据闭环 - 大规模定制 - 红领/酷特智能案例 - 在线定制 → 自动排产 → 7天交付 - 成本接近成衣 ### AII三大体系（中国架构） - 网络体系：连得上连得快 - 平台体系：存得下算得动 - 安全体系：不被攻不瘫痪 - 与IIRA对应关系 ### 五大构成要素 - 感知层：传感器/RFID/工业相机 - 网络层：现场总线/工业以太网/4G/5G/LoRa - 平台层：阿里云IoT/华为云IoT/树根互联/卡奥斯 - 应用层：MES/SCADA/WMS/QMS - 安全层：贯穿各层 ### 典型应用场景 - 预测性维护：非计划停机减30-50% - 远程运维：出差减40%+ - 能耗优化：降低10-20% - 质量追溯：定位从数天缩至数分钟 - 产线协同：交付周期缩短20-30% - 大规模定制 ### 产业生态四类角色 - 设备制造商：西门子/ABB/发那科/汇川 - 平台提供商：阿里云IoT/华为云IoT/树根互联/卡奥斯 - 系统集成商 - 最终用户 ### 商业模式变革 - 劳斯莱斯"按小时卖推力"（Power by the Hour） - 空压机"卖压缩空气"（阿特拉斯·科普柯/凯撒） - 三一重工"挖掘机指数"（从卖产品到卖服务） ## 2.4 动手实践：云服务器注册与远程登录 ### 实践任务 - 注册云平台账号并创建云服务器 - 阿里云ECS - Ubuntu 22.04，1核1GB - 公网IP访问 - 配置安全组规则 - 开放SSH端口22（入方向） - 类比防火墙入站规则 - 0.0.0.0/0表示允许所有IP - SSH登录云服务器并执行基本操作 - timedatectl、curl wttr.in - 本地虚拟机 vs 云服务器对比 - 物理位置、访问方式、性能、网络、费用、关机后状态 ## 🎯 课程思政 - 制造强国：从"世界工厂"到"制造强国"，工业互联网是历史机遇',-1)])])}const u=a(n,[["render",d]]);export{p as __pageData,u as default};
